// Turns the JSON in data/ into compile-time Rust constants.
//
// The Rust core has ZERO dependencies — no serde, no JSON parsing, no file I/O
// at all. That is partly forced (the crates.io registry is not reachable from
// the build environment) and partly the right answer anyway: a crate whose
// language data is a compile-time constant cannot load the wrong file, cannot
// fail at startup, and compiles straight to WASM with nothing to bundle.
//
// The generated file is checked in. Regenerate it with `npm run rust:data`
// whenever data/ changes; a test on the TypeScript side fails if it is stale,
// so the two can never disagree about what the language is.
//
// Plain .mjs rather than .ts so it runs under bare node on any machine in this
// project's toolchain, with or without tsx.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";

const root = process.argv[2];
// Optional second root for the generated output, so the generator can read the
// data from one checkout and write the crate into another.
const outRoot = process.argv[3] ?? root;
if (!root) {
  console.error("usage: node scripts/buildRustData.mjs <repo-root> [out-root]");
  process.exit(1);
}

const read = (p) => JSON.parse(readFileSync(join(root, p), "utf8"));
const phonology = read("data/phonology/phonology.json");

const str = (s) => JSON.stringify(s);
const strSlice = (arr) => `&[${arr.map(str).join(", ")}]`;

const lines = [];
const w = (s = "") => lines.push(s);

w("// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.");
w("//");
w("// Compiled from the JSON in data/, which is the single source of truth for");
w("// the language. Edit the JSON and run `npm run rust:data`; editing this file");
w("// directly puts Rust and TypeScript into disagreement about what Gurzûl Khar");
w("// is, which is exactly what the shared fixtures exist to prevent.");
w(`// Source data version: phonology ${phonology.version}`);
w();
w("/// A consonant as declared in data/phonology/phonology.json.");
w("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
w("pub struct Consonant {");
w("    /// Phonology id, e.g. `\"kh\"`.");
w("    pub id: &'static str,");
w("    /// How it is written.");
w("    pub latin: &'static str,");
w("    /// How it is pronounced.");
w("    pub ipa: &'static str,");
w("    /// Place of articulation.");
w("    pub place: &'static str,");
w("    /// Manner of articulation.");
w("    pub manner: &'static str,");
w("    /// Voiced or voiceless.");
w("    pub voicing: &'static str,");
w("    /// Where in a word it may occur: initial, medial, final.");
w("    pub positions: &'static [&'static str],");
w("}");
w();
w("/// A vowel: short, long, or a diphthong. `written_variants` carries accepted");
w("/// alternate spellings of the SAME vowel — \"ü\" is a written variant of \"û\".");
w("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
w("pub struct Vowel {");
w("    /// Phonology id, e.g. `\"\u00fb\"`.");
w("    pub id: &'static str,");
w("    /// How it is written.");
w("    pub latin: &'static str,");
w("    /// How it is pronounced.");
w("    pub ipa: &'static str,");
w("    /// True for a long vowel. Length is meaningful: it distinguishes words.");
w("    pub is_long: bool,");
w("    /// True for a diphthong.");
w("    pub is_diphthong: bool,");
w("    /// Accepted alternate spellings of this same vowel.");
w("    pub written_variants: &'static [&'static str],");
w("}");
w();

w("/// Every consonant the language declares, in data order.");
w("pub static CONSONANTS: &[Consonant] = &[");
for (const c of phonology.consonants) {
  w(`    Consonant { id: ${str(c.id)}, latin: ${str(c.latin)}, ipa: ${str(c.ipa)}, place: ${str(c.place)}, manner: ${str(c.manner)}, voicing: ${str(c.voicing)}, positions: ${strSlice(c.positions)} },`);
}
w("];");
w();

const vowelRows = (list, isLong, isDiph) =>
  list.map(
    (v) =>
      `    Vowel { id: ${str(v.id)}, latin: ${str(v.latin)}, ipa: ${str(v.ipa)}, is_long: ${isLong}, is_diphthong: ${isDiph}, written_variants: ${strSlice(v.writtenVariants ?? [])} },`
  );

w("/// The short vowels.");
w("pub static SHORT_VOWELS: &[Vowel] = &[");
vowelRows(phonology.vowels.short, false, false).forEach(w);
w("];");
w();
w("/// The long vowels. A circumflex marks length, and length changes the word.");
w("pub static LONG_VOWELS: &[Vowel] = &[");
vowelRows(phonology.vowels.long, true, false).forEach(w);
w("];");
w();
w("/// The diphthongs, each a single atomic nucleus.");
w("pub static DIPHTHONGS: &[Vowel] = &[");
vowelRows(phonology.vowels.diphthongs, false, true).forEach(w);
w("];");
w();

w("/// Two-consonant onsets the phonotactics permit.");
w(`pub static ONSET_CLUSTERS: &[&str] = ${strSlice(phonology.phonotactics.onsetClusters.allowed)};`);
w();
w("/// Two-consonant codas the phonotactics permit.");
w(`pub static CODA_CLUSTERS: &[&str] = ${strSlice(phonology.phonotactics.codaClusters.allowed)};`);
w();
w(`/// ${phonology.stress.defaultRule}`);
w("/// The default stress rule, as documented.");
w("pub static STRESS_DEFAULT_RULE: &str = " + str(phonology.stress.defaultRule) + ";");
w();

const outPath = join(outRoot, "crates/gkh-core/src/data/generated.rs");
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, lines.join("\n") + "\n", "utf8");
console.log(`wrote ${outPath} (${phonology.consonants.length} consonants, ${phonology.vowels.short.length + phonology.vowels.long.length + phonology.vowels.diphthongs.length} vowels)`);

// --- test fixtures -------------------------------------------------------
const fixtures = read("tests/fixtures/phonotactics.json");
const fx = [];
fx.push("// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.");
fx.push("//");
fx.push("// The SAME cases tests/phonotacticFixture.test.ts asserts on the TypeScript");
fx.push("// side. If the two engines ever disagree about one of these words, one of");
fx.push("// the two suites goes red — which is the whole point of the port.");
fx.push("");
fx.push("/// One pinned word and the violations it must produce.");
fx.push("pub struct FixtureCase {");
fx.push("    /// The word under test.");
fx.push("    pub word: &'static str,");
fx.push("    /// Whether it is fully legal.");
fx.push("    pub valid: bool,");
fx.push("    /// The violation codes it must produce, in order.");
fx.push("    pub codes: &'static [&'static str],");
fx.push("}");
fx.push("");
fx.push("/// The shared phonotactic fixtures.");
fx.push("pub static PHONOTACTIC_CASES: &[FixtureCase] = &[");
for (const c of fixtures.cases) {
  fx.push(`    FixtureCase { word: ${str(c.word)}, valid: ${c.valid}, codes: ${strSlice(c.codes)} },`);
}
fx.push("];");
const fxPath = join(outRoot, "crates/gkh-core/tests/generated/phonotactics.rs");
mkdirSync(dirname(fxPath), { recursive: true });
writeFileSync(fxPath, fx.join("\n") + "\n", "utf8");
console.log(`wrote ${fxPath} (${fixtures.cases.length} cases)`);

// --- coiner data ---------------------------------------------------------
const weights = read("data/phonology/coinerWeights_v1.json");
const reserved = read("data/lexicon/coinerReserved_v1.json");

const cw = [];
const cwLine = (x = "") => cw.push(x);
cwLine("// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.");
cwLine("//");
cwLine("// coiner_v1's frozen weight tables and the reserved spellings it avoids.");
cwLine("// Both are FROZEN: changing either changes every word the coiner has ever");
cwLine("// produced. See data/phonology/coinerWeights_v1.json for the full note.");
cwLine();
cwLine("/// One weighted unit in a selection table.");
cwLine("pub struct WeightedUnit {");
cwLine("    /// The spelling this unit contributes.");
cwLine("    pub unit: &'static str,");
cwLine("    /// Its observed frequency in the hand-authored lexicon.");
cwLine("    pub weight: u64,");
cwLine("}");
cwLine();
const table = (name, rows, doc) => {
  cwLine(`/// ${doc}`);
  cwLine(`pub static ${name}: &[WeightedUnit] = &[`);
  for (const r of rows) cwLine(`    WeightedUnit { unit: ${str(r.unit)}, weight: ${r.weight} },`);
  cwLine("];");
  cwLine();
};
table("ONSET_INITIAL", weights.onsetInitial, "Word-initial onsets, by observed frequency.");
table("ONSET_MEDIAL", weights.onsetMedial, "Word-medial onsets, by observed frequency.");
table("NUCLEI", weights.nuclei, "Vowel nuclei, by observed frequency.");
table("CODA_FINAL", weights.codaFinal, "Word-final codas, by observed frequency.");
table("CODA_MEDIAL", weights.codaMedial, "Word-medial codas, by observed frequency.");

cwLine("/// Below this roll a word gets one syllable.");
cwLine(`pub static SYLLABLE_ONE_PERCENT: u64 = ${weights.syllableCount.onePercent};`);
cwLine("/// Below this roll (and at or above the previous) a word gets two.");
cwLine(`pub static SYLLABLE_TWO_PERCENT: u64 = ${weights.syllableCount.twoPercent};`);
cwLine("/// How often a first syllable has an onset at all, as a percentage.");
cwLine(`pub static ONSET_FIRST_PERCENT: u64 = ${weights.presence.onsetFirstPercent};`);
cwLine("/// How often a later syllable has an onset, as a percentage.");
cwLine(`pub static ONSET_MEDIAL_PERCENT: u64 = ${weights.presence.onsetMedialPercent};`);
cwLine("/// How often a final syllable has a coda, as a percentage.");
cwLine(`pub static CODA_FINAL_PERCENT: u64 = ${weights.presence.codaFinalPercent};`);
cwLine("/// How often a non-final syllable has a coda, as a percentage.");
cwLine(`pub static CODA_MEDIAL_PERCENT: u64 = ${weights.presence.codaMedialPercent};`);
cwLine("/// How often a nucleus is long, as a percentage.");
cwLine(`pub static LONG_VOWEL_PERCENT: u64 = ${weights.presence.longVowelPercent};`);
cwLine();
cwLine("/// Hand-authored spellings as they stood when coiner_v1 was frozen. The");
cwLine("/// coiner avoids these, and deliberately NOT the live lexicon, so the");
cwLine("/// dictionary can grow without moving a single coined word.");
cwLine(`pub static RESERVED_FORMS: &[&str] = ${strSlice(reserved.forms)};`);

const cwPath = join(outRoot, "crates/gkh-core/src/data/coiner_generated.rs");
mkdirSync(dirname(cwPath), { recursive: true });
writeFileSync(cwPath, cw.join("\n") + "\n", "utf8");
console.log(`wrote ${cwPath} (${reserved.forms.length} reserved forms)`);

// --- golden fixture ------------------------------------------------------
// Emitted as one tab-separated string rather than 10,549 struct literals:
// same data, a fraction of the compile time, and no parser needed beyond
// split(). Lemmas never contain a tab or a newline, which the generator
// asserts rather than assumes.
const golden = read("tests/fixtures/coiner_v1.golden.json");
const rows = golden.cases.map((c) => {
  for (const field of [c.lemma, c.pos, c.lang, c.gkh]) {
    if (/[\t\n\r]/.test(field)) throw new Error(`golden field contains a tab or newline: ${JSON.stringify(field)}`);
  }
  return `${c.lemma}\t${c.pos}\t${c.lang}\t${c.gkh}\t${c.attempt}`;
});
const gold = [
  "// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.",
  "//",
  "// The SAME coinages tests/coinerGolden.test.ts pins on the TypeScript side.",
  "// Tab-separated: lemma, pos, lang, gkh, attempt — one per line, in the order",
  "// they were coined, because each reserves its spelling against the next.",
  "",
  "/// Every pinned coinage, tab-separated, newline-delimited.",
  `pub static GOLDEN_TSV: &str = ${JSON.stringify(rows.join("\n"))};`,
  "",
].join("\n");
const goldPath = join(outRoot, "crates/gkh-core/tests/generated/coiner_golden.rs");
mkdirSync(dirname(goldPath), { recursive: true });
writeFileSync(goldPath, gold, "utf8");
console.log(`wrote ${goldPath} (${rows.length} cases)`);

// --- lexicon -------------------------------------------------------------
// The hand-authored vocabulary. Its `ipa` field is derived from the engine
// (see tests/lexiconIpa.test.ts), which makes the lexicon itself a fixture:
// every entry is a pinned case for the Rust IPA port to reproduce.
const lexicon = read("data/lexicon/lexicon.json");
const lx = [];
const lxLine = (x = "") => lx.push(x);
lxLine("// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.");
lxLine();
lxLine("/// One hand-authored word.");
lxLine("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
lxLine("pub struct Entry {");
lxLine("    /// Stable identifier, e.g. `\"nou-001\"`.");
lxLine("    pub id: &'static str,");
lxLine("    /// The Gurzûl Khar spelling.");
lxLine("    pub gkh: &'static str,");
lxLine("    /// IPA, derived from the engine rather than hand-written.");
lxLine("    pub ipa: &'static str,");
lxLine("    /// Part of speech.");
lxLine("    pub pos: &'static str,");
lxLine("    /// English gloss. May carry alternatives separated by `/`.");
lxLine("    pub en: &'static str,");
lxLine("    /// Dutch gloss. May carry alternatives separated by `/`.");
lxLine("    pub nl: &'static str,");
lxLine("    /// The root this is built from, when it is a derived form.");
lxLine("    pub root: Option<&'static str>,");
lxLine("}");
lxLine();
lxLine("/// Every hand-authored entry, in data order.");
lxLine("pub static ENTRIES: &[Entry] = &[");
for (const e of lexicon.entries) {
  const root = e.root ? `Some(${str(e.root)})` : "None";
  lxLine(`    Entry { id: ${str(e.id)}, gkh: ${str(e.gkh)}, ipa: ${str(e.ipa)}, pos: ${str(e.pos)}, en: ${str(e.en)}, nl: ${str(e.nl ?? "")}, root: ${root} },`);
}
lxLine("];");
lxLine();
lxLine("/// Derivational suffixes and what they do.");
lxLine("pub static DERIVATIONAL_AFFIXES: &[(&str, &str)] = &[");
for (const a of lexicon.derivationalAffixes ?? []) {
  lxLine(`    (${str(a.suffix)}, ${str(a.function)}),`);
}
lxLine("];");

const lxPath = join(outRoot, "crates/gkh-core/src/data/lexicon_generated.rs");
mkdirSync(dirname(lxPath), { recursive: true });
writeFileSync(lxPath, lx.join("\n") + "\n", "utf8");
console.log(`wrote ${lxPath} (${lexicon.entries.length} entries)`);

// --- lemmatisation fixtures ---------------------------------------------
const lemmaFx = read("tests/fixtures/lemmatization.json");
const lemmaRows = lemmaFx.cases.map((c) => {
  const kind = c.kind ?? "";
  const gkh = c.gkh ?? "";
  const parts = (c.parts ?? []).join("|");
  return `${c.word}\t${c.lang}\t${kind}\t${gkh}\t${parts}`;
});
const lemmaOut = [
  "// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.",
  "//",
  "// The SAME cases tests/lemmatizer.test.ts asserts. Tab-separated: word,",
  "// lang, kind, gkh, parts (pipe-separated). An empty kind means the lexicon",
  "// cannot account for the word and it is coined instead — a pinned outcome,",
  "// not a failure.",
  "",
  "/// The shared lemmatisation fixtures.",
  `pub static LEMMA_TSV: &str = ${JSON.stringify(lemmaRows.join("\n"))};`,
  "",
].join("\n");
const lemmaPath = join(outRoot, "crates/gkh-core/tests/generated/lemmatization.rs");
mkdirSync(dirname(lemmaPath), { recursive: true });
writeFileSync(lemmaPath, lemmaOut, "utf8");
console.log(`wrote ${lemmaPath} (${lemmaRows.length} cases)`);

// --- grammar -------------------------------------------------------------
const grammar = read("data/morphology/grammar.json");
const strip = (x) => String(x).replace(/^-/, "");
const gm = [];
const gmLine = (x = "") => gm.push(x);
gmLine("// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.");
gmLine("//");
gmLine("// Grammar constants from data/morphology/grammar.json. Every affix and");
gmLine("// particle the engine uses is read from there, never hardcoded, so the");
gmLine("// grammar reference page and the translator can never drift apart.");
gmLine();
gmLine("/// Plural suffix on a noun root.");
gmLine(`pub static PLURAL_SUFFIX: &str = ${str(strip(grammar.nouns.pluralSuffix))};`);
gmLine("/// Allomorph used when the root already ends in -k, avoiding a geminate.");
gmLine(`pub static PLURAL_EPENTHETIC: &str = ${str("ak" + strip(grammar.nouns.pluralSuffix))};`);
gmLine();
gmLine("/// Tense suffixes, keyed by tense name.");
gmLine("pub static TENSE_SUFFIXES: &[(&str, &str)] = &[");
for (const [t, suf] of Object.entries(grammar.verbs.tenseSuffixes)) gmLine(`    (${str(t)}, ${str(strip(suf))}),`);
gmLine("];");
gmLine();
gmLine("/// Possessive suffixes, keyed by person.");
gmLine("pub static POSSESSIVE_SUFFIXES: &[(&str, &str)] = &[");
for (const [p2, suf] of Object.entries(grammar.pronouns.possessiveSuffixes)) gmLine(`    (${str(p2)}, ${str(strip(suf))}),`);
gmLine("];");
gmLine();
gmLine("/// Subject pronoun forms, keyed by person.");
gmLine("pub static SUBJECT_FORMS: &[(&str, &str)] = &[");
for (const [p2, form] of Object.entries(grammar.pronouns.subjectForms)) gmLine(`    (${str(p2)}, ${str(form)}),`);
gmLine("];");
gmLine();
gmLine("/// Interrogative words, keyed by the English question word.");
gmLine("pub static INTERROGATIVES: &[(&str, &str)] = &[");
for (const [q, form] of Object.entries(grammar.pronouns.interrogatives)) gmLine(`    (${str(q)}, ${str(form)}),`);
gmLine("];");
gmLine();
const superMarker = String(grammar.adjectives.superlative.marker).match(/-(\S+)/);
gmLine("/// Marker placed before a comparative or superlative adjective.");
gmLine(`pub static COMPARATIVE_MARKER: &str = ${str(grammar.adjectives.comparative.marker)};`);
gmLine("/// Suffix that makes a comparative into a superlative.");
gmLine(`pub static SUPERLATIVE_SUFFIX: &str = ${str(superMarker ? superMarker[1] : "gûl")};`);
gmLine("/// Intensifier placed before an adjective.");
gmLine(`pub static INTENSIFIER: &str = ${str(grammar.adjectives.intensification.marker)};`);
gmLine("/// Particle placed before the finite verb to negate it.");
gmLine(`pub static NEGATION_PARTICLE: &str = ${str(grammar.verbs.negation.particle)};`);
gmLine("/// Sentence-final particle marking a yes/no question.");
gmLine('pub static QUESTION_PARTICLE: &str = "ma";');
gmLine("/// Relativiser: `[head noun] kha [clause]`.");
gmLine('pub static RELATIVISER: &str = "kha";');
gmLine("/// Possession postposition: `[possessum] ta [possessor]`.");
gmLine(`pub static POSSESSION_MARKER: &str = ${str(grammar.nouns.possession.marker)};`);
gmLine();
gmLine("/// Coordinating conjunctions, keyed by their English sense.");
gmLine("pub static COORDINATION: &[(&str, &str)] = &[");
for (const [k, v] of Object.entries(grammar.syntax.coordination)) gmLine(`    (${str(k)}, ${str(v)}),`);
gmLine("];");

const gmPath = join(outRoot, "crates/gkh-core/src/data/grammar_generated.rs");
mkdirSync(dirname(gmPath), { recursive: true });
writeFileSync(gmPath, gm.join("\n") + "\n", "utf8");
console.log(`wrote ${gmPath}`);

// --- translation fixtures ------------------------------------------------
const transFx = read("tests/fixtures/translation.json");
const transRows = transFx.cases.map((c) => {
  const coined = (c.coined ?? []).map((x) => `${x.source}>${x.gkh}`).join("|");
  const never = (c.neverUnknown ?? []).join("|");
  return [c.name, c.direction, c.input, c.expect, c.output ?? "", c.unknownWord ?? "", never, coined].join("\t");
});
const transOut = [
  "// @generated by scripts/buildRustData.mjs — DO NOT EDIT BY HAND.",
  "//",
  "// The SAME cases tests/regression.test.ts asserts. Tab-separated: name,",
  "// direction, input, expect, output, unknownWord, neverUnknown (pipe-",
  "// separated), coined (source>gkh, pipe-separated).",
  "",
  "/// The shared translation fixtures.",
  `pub static TRANSLATION_TSV: &str = ${JSON.stringify(transRows.join("\n"))};`,
  "",
].join("\n");
const transPath = join(outRoot, "crates/gkh-core/tests/generated/translation.rs");
mkdirSync(dirname(transPath), { recursive: true });
writeFileSync(transPath, transOut, "utf8");
console.log(`wrote ${transPath} (${transRows.length} cases)`);
